import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.169.0/build/three.module.js';

const $=s=>document.querySelector(s), canvas=$('#scene');
const renderer=new THREE.WebGLRenderer({canvas,antialias:true,alpha:false});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.1;
const scene=new THREE.Scene();scene.background=new THREE.Color('#a9c5b5');scene.fog=new THREE.FogExp2('#a9c5b5',.009);
const camera=new THREE.PerspectiveCamera(51,innerWidth/innerHeight,.1,220);camera.position.set(0,1.75,9);camera.lookAt(0,2.55,-25);
scene.add(new THREE.HemisphereLight('#d8e6d3','#566149',2));
const sun=new THREE.DirectionalLight('#fff0ce',3);sun.position.set(-15,28,12);sun.castShadow=true;sun.shadow.mapSize.set(1024,1024);sun.shadow.camera.left=-55;sun.shadow.camera.right=55;sun.shadow.camera.top=55;sun.shadow.camera.bottom=-55;scene.add(sun);
const mat=(color,roughness=.9)=>new THREE.MeshStandardMaterial({color,roughness});
const materials={grass:mat('#758666'),darkgrass:mat('#667b5d'),trunk:mat('#564b3b'),leaf:mat('#4b7057'),leaf2:mat('#658466'),wood:mat('#6a533b'),cream:mat('#eee4c9'),red:mat('#bd634c'),blue:mat('#455b4d'),gold:mat('#e0b969'),metal:mat('#5f695e',.36)};
function mesh(geometry,material,x,y,z,parent=scene){const m=new THREE.Mesh(geometry,material);m.position.set(x,y,z);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m;}
// Soft rolling practice field and layered distant ridgelines.
const ground=mesh(new THREE.PlaneGeometry(200,190,1,1),materials.grass,0,-.18,-43);ground.rotation.x=-Math.PI/2;
for(let r=0;r<4;r++){const points=[];for(let i=0;i<32;i++){const x=-105+i*6.8;const y=9+r*3+Math.sin(i*.62+r*1.5)*4+Math.sin(i*.24+r)*2;points.push(new THREE.Vector2(x,y));}const shape=new THREE.Shape(points);shape.lineTo(115,-2);shape.lineTo(-110,-2);const geo=new THREE.ShapeGeometry(shape);const m=mesh(geo,mat(['#789787','#718878','#657e72','#587267'][r]),0,0,-85-r*13);m.material.side=THREE.DoubleSide;}
const rand=(a,b)=>a+Math.random()*(b-a);
function addTree(x,z,scale=1){const group=new THREE.Group();group.position.set(x,0,z);group.scale.setScalar(scale);scene.add(group);mesh(new THREE.CylinderGeometry(.13,.21,2.4,7),materials.trunk,0,1.2,0,group);for(let n=0;n<3;n++){const crown=mesh(new THREE.ConeGeometry(1.05-n*.14,2.5,7),n===1?materials.leaf2:materials.leaf,0,2.45+n*.7,0,group);crown.rotation.y=rand(0,6);}}
for(let side of [-1,1])for(let i=0;i<19;i++){const z=3-i*5.2;addTree(side*rand(8,17),z,rand(.72,1.3));}
// Low shrubs add depth to the edge of the lane.
for(let i=0;i<35;i++){const x=(Math.random()<.5?-1:1)*rand(5,13),z=rand(-64,4);const b=mesh(new THREE.IcosahedronGeometry(rand(.35,.8),1),i%3?materials.leaf:materials.leaf2,x,rand(.3,.55),z);b.scale.y=.7;}
const boardGroup=new THREE.Group();scene.add(boardGroup);let targetRadius=1.25,targetCenter=new THREE.Vector3(0,2.7,-25);let boardFace;
function buildTarget(){while(boardGroup.children.length){const c=boardGroup.children.pop();c.geometry?.dispose();}boardGroup.position.set(0,0,-state.distance);targetCenter.set(0,2.65,-state.distance);targetRadius=state.targetId===0?1.25:state.targetId===1?1.42:state.targetId===2?1.55:1.35;
 const stand=mesh(new THREE.CylinderGeometry(.075,.11,2.55,9),materials.wood,0,1.28,0,boardGroup);stand.position.z=-.12;
 const cross=mesh(new THREE.BoxGeometry(1.55,.09,.13),materials.wood,0,1.72,-.12,boardGroup);
 mesh(new THREE.BoxGeometry(.15,.16,.18),materials.metal,-.58,2.56,-.11,boardGroup);mesh(new THREE.BoxGeometry(.15,.16,.18),materials.metal,.58,2.56,-.11,boardGroup);
 const radii=[1,.78,.56,.35,.17];const colors=[materials.blue,materials.cream,materials.red,materials.gold,materials.red];
 radii.forEach((f,i)=>{const radius=targetRadius*f;mesh(new THREE.CylinderGeometry(radius,radius,.12,64),colors[i],0,2.68,-i*.014,boardGroup).rotation.x=Math.PI/2;});
 // outer rim, concentric scoring wire, and sunlit support details
 for(let i=0;i<5;i++){const ring=mesh(new THREE.TorusGeometry(targetRadius*radii[i],i===0?.025:.014,7,72),i===0?materials.wood:materials.cream,0,2.68,.04,boardGroup);ring.rotation.x=0;}
 const rim=mesh(new THREE.TorusGeometry(targetRadius,.055,8,72),materials.wood,0,2.68,.06,boardGroup);
 boardFace=new THREE.Group();boardFace.position.set(0,2.68,.1);boardGroup.add(boardFace);
}
function addBow(){const bow=new THREE.Group();camera.add(bow);bow.position.set(.66,-.52,-1.55);bow.rotation.set(.04,-.04,-.11);const dark=new THREE.MeshStandardMaterial({color:'#3b3027',roughness:.48});const accent=new THREE.MeshStandardMaterial({color:'#b8a36f',metalness:.45,roughness:.35});const curve=new THREE.CatmullRomCurve3([new THREE.Vector3(-.25,-.6,0),new THREE.Vector3(-.42,-.33,0),new THREE.Vector3(-.39,0,0),new THREE.Vector3(-.27,.33,0),new THREE.Vector3(-.14,.55,0)]);bow.add(new THREE.Mesh(new THREE.TubeGeometry(curve,24,.035,8,false),dark));const string=new THREE.BufferGeometry().setFromPoints([new THREE.Vector3(-.14,.55,0),new THREE.Vector3(-.27,0,.01),new THREE.Vector3(-.25,-.6,0)]);bow.add(new THREE.Line(string,new THREE.LineBasicMaterial({color:'#ddd5b9'})));const grip=mesh(new THREE.CylinderGeometry(.07,.08,.28,10),accent, -.31,-.02,.04,bow);grip.rotation.z=.12;const arrowShaft=mesh(new THREE.CylinderGeometry(.012,.012,.88,7),mat('#c7a973',.55),-.18,0,.04,bow);arrowShaft.rotation.z=Math.PI/2;bowGroup=bow;}
