bowGroup=bow;}
const areas=[
 {name:'Pine Hollow',price:0,dist:25,weather:'Clear morning',sky:'#a9c5b5',fog:'#a9c5b5',ground:'#758666',wind:'3.2'},
 {name:'Redrock Basin',price:70,dist:32,weather:'Dry canyon breeze',sky:'#d5b08c',fog:'#c89b73',ground:'#a77b57',wind:'4.6'},
 {name:'Highmere Pass',price:160,dist:38,weather:'Mountain air',sky:'#acc6ce',fog:'#acc6ce',ground:'#718783',wind:'5.4'},
 {name:'Moonlit Grove',price:320,dist:29,weather:'Evening calm',sky:'#7e9a99',fog:'#708685',ground:'#536a5d',wind:'2.1'}
];
const targets=[
 {name:'Classic face',price:0,dist:25,hit:1,bull:3,face:'Standard club target'},
 {name:'Field champion',price:35,dist:31,hit:2,bull:5,face:'A little farther, a better purse'},
 {name:'Gilded roundel',price:90,dist:38,hit:3,bull:8,face:'Premium rings · premium rewards'},
 {name:'Spirit mark',price:175,dist:34,hit:5,bull:12,face:'The range favorite for experts'}
];
const upgrades=[
 {id:'limbs',tab:'bow',name:'Reflex limbs',icon:'⌁',desc:'More snap through the shot. Arrows fly faster at long range.',max:4,prices:[8,17,30,48]},
 {id:'grip',tab:'bow',name:'Balanced riser',icon:'♧',desc:'A calmer hold steadies your release and smooths each shot.',max:3,prices:[12,25,42]},
 {id:'sight',tab:'bow',name:'Brass pin sight',icon:'◎',desc:'Tune your wind correction with a clearer, steadier sight picture.',max:4,prices:[10,22,38,60]},
 {id:'carbon',tab:'arrows',name:'Carbon shafts',icon:'↗',desc:'Light, straight shafts keep their line at longer distances.',max:4,prices:[9,19,34,52]},
 {id:'fletch',tab:'arrows',name:'Stabilizer fletch',icon:'⋈',desc:'A tighter flight pattern resists gusts and groups arrows closer.',max:4,prices:[11,23,39,58]},
 {id:'points',tab:'arrows',name:'Match field points',icon:'◆',desc:'Precisely weighted tips help your arrows track where you aim.',max:3,prices:[13,28,46]}
];
const defaultState={coins:12,areaId:0,targetId:0,unlockedAreas:[0],unlockedTargets:[0],upgrades:{},shot:1,round:0};
let state;try{state={...defaultState,...JSON.parse(localStorage.getItem('wildshot-save')||'{}')};state.upgrades={...defaultState.upgrades,...state.upgrades};state.unlockedAreas=state.unlockedAreas||[0];state.unlockedTargets=state.unlockedTargets||[0];}catch{state={...defaultState,upgrades:{}};}
state.areaId=Math.min(state.areaId,areas.length-1);state.targetId=Math.min(state.targetId,targets.length-1);state.distance=targets[state.targetId].dist;let windPower=.32,windSign=1,windTime=0,aim={x:.5,y:.48},shots=[],arrowStamps=[],charging=false,chargeAt=0,power=0,roundDone=false,drawerTab='bow',soundOn=true,audio;
function save(){try{localStorage.setItem('wildshot-save',JSON.stringify(state));}catch{}}
function setWind(){windSign=Math.random()<.5?-1:1;windPower=rand(.18,.75);const direction=windSign>0?'E':'W';$('#windDir').textContent=direction;$('#windSpeed').textContent=(windPower*9.5).toFixed(1);$('#windArrow').textContent=windSign>0?'➜':'⬅';$('#windArrow').style.transform=windSign<0?'scaleX(-1)':'';$('#windMeter').style.width=`${Math.round(windPower*100)}%`;}
function refreshHud(){const area=areas[state.areaId],target=targets[state.targetId];$('#coins').textContent=state.coins;$('#areaName').textContent=area.name;$('#weatherName').textContent=area.weather;$('#targetName').textContent=target.name;$('#distance').textContent=state.distance;$('#shotCount').textContent=String(state.shot).padStart(2,'0');$('#bowName').textContent=`Field bow · ${['I','II','III','IV','V'][state.upgrades.limbs||0]}`;}
function updateEnvironment(){const a=areas[state.areaId];scene.background.set(a.sky);scene.fog.color.set(a.fog);materials.grass.color.set(a.ground);camera.far=220;camera.updateProjectionMatrix();state.distance=targets[state.targetId].dist+ (state.areaId===0?0:Math.round((areas[state.areaId].dist-25)*.35));buildTarget();refreshHud();}
function toast(title,copy,type='lime'){const el=$('#toast');el.className=`toast ${type} show`;$('#toastTitle').textContent=title;$('#toastCopy').textContent=copy;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),2100);}
function sound(frequency=600){if(!soundOn)return;try{audio=audio||new AudioContext();const o=audio.createOscillator(),g=audio.createGain();o.frequency.value=frequency;o.type='sine';g.gain.setValueAtTime(.07,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.18);o.connect(g);g.connect(audio.destination);o.start();o.stop(audio.currentTime+.19);}catch{}}
function openDrawer(tab='bow'){drawerTab=tab;$('#drawerBackdrop').classList.add('open');renderDrawer();}
function renderDrawer(){const shop=$('#shopTabs');shop.style.display='flex';$('#drawerTitle').textContent=drawerTab==='areas'?'Choose your range':'Bowyer\'s bench';$('#drawerSub').textContent=drawerTab==='areas'?'Unlock a new landscape and find your next mark.':'Tune your kit for the shot ahead.';shop.querySelectorAll('.tab').forEach(t=>t.classList.toggle('active',t.dataset.tab===drawerTab));const content=$('#drawerContent');
 if(drawerTab==='areas'){content.innerHTML=`<div class="area-list">${areas.map((a,i)=>{const unlocked=state.unlockedAreas.includes(i),selected=state.areaId===i;return `<div class="area-item"><div class="area-thumb"><i></i></div><div class="area-text"><strong>${a.name}</strong><small>${a.weather} · ${a.dist} m range</small></div><button class="area-action ${selected?'selected':''}" data-area="${i}" ${!unlocked&&state.coins<a.price?'disabled':''}>${selected?'ACTIVE':unlocked?'ENTER':`● ${a.price}`}</button></div>`;}).join('')}</div>`;
 content.querySelectorAll('[data-area]').forEach(btn=>btn.onclick=()=>{const id=+btn.dataset.area,a=areas[id];if(state.unlockedAreas.includes(id)){state.areaId=id;updateEnvironment();setWind();save();renderDrawer();}else if(state.coins>=a.price){state.coins-=a.price;state.unlockedAreas.push(id);state.areaId=id;updateEnvironment();setWind();save();renderDrawer();toast('New range unlocked',a.name,'gold');}});return;}
 if(drawerTab==='targets'){content.innerHTML=`<div class="shop-list">${targets.map((t,i)=>{const unlocked=state.unlockedTargets.includes(i),selected=state.targetId===i;return `<div class="shop-item"><div class="shop-emoji">${['🎯','🏹','✹','✧'][i]}</div><div class="shop-desc"><strong>${t.name}</strong><small>${t.dist} m · ${t.face}<br>Hit +${t.hit} coins · Bull's-eye +${t.bull}</small></div><button class="buy-btn" data-target="${i}" ${!unlocked&&state.coins<t.price?'disabled':''}>${selected?'ACTIVE':unlocked?'SELECT':`● ${t.price}`}</button></div>`;}).join('')}</div>`;
 content.querySelectorAll('[data-target]').forEach(btn=>btn.onclick=()=>{const id=+btn.dataset.target,t=targets[id];if(state.unlockedTargets.includes(id)){state.targetId=id;updateEnvironment();save();renderDrawer();}else if(state.coins>=t.price){state.coins-=t.price;state.unlockedTargets.push(id);state.targetId=id;updateEnvironment();save();renderDrawer();toast('New target unlocked',`${t.name} · improved rewards`,'gold');}});return;}
 const items=upgrades.filter(u=>u.tab===drawerTab);content.innerHTML=`<div class="shop-list">${items.map(u=>{const level=state.upgrades[u.id]||0,maxed=level>=u.max,cost=u.prices[level]??0;return `<div class="shop-item"><div class="shop-emoji">${u.icon}</div><div class="shop-desc"><strong>${u.name}</strong><small>${u.desc}</small><div class="shop-level">LEVEL ${level} / ${u.max}</div></div><button class="buy-btn" data-upgrade="${u.id}" ${maxed||state.coins<cost?'disabled':''}>${maxed?'MAX':`● ${cost}`}</button></div>`;}).join('')}</div>`;
 content.querySelectorAll('[data-upgrade]').forEach(btn=>btn.onclick=()=>{const u=upgrades.find(x=>x.id===btn.dataset.upgrade),level=state.upgrades[u.id]||0,cost=u.prices[level];if(cost!=null&&state.coins>=cost){state.coins-=cost;state.upgrades[u.id]=level+1;save();refreshHud();renderDrawer();sound(780);}});
}

