function makeArrow(){const g=new THREE.Group(),shaft=new THREE.Mesh(new THREE.CylinderGeometry(.013,.013,.88,7),mat('#c9aa72',.52));shaft.position.y=0;g.add(shaft);const tip=new THREE.Mesh(new THREE.ConeGeometry(.045,.17,7),mat('#9ca49a',.32));tip.position.y=.51;g.add(tip);const tail=new THREE.MeshStandardMaterial({color:'#c56e52',side:THREE.DoubleSide,roughness:.65});for(let i=0;i<3;i++){const f=new THREE.Mesh(new THREE.PlaneGeometry(.14,.08),tail);f.position.set(0,-.34,0);f.rotation.y=i*Math.PI/3;g.add(f);}g.castShadow=true;scene.add(g);return g;}
function getAimPoint(){camera.updateMatrixWorld();const raycaster=new THREE.Raycaster();raycaster.setFromCamera(new THREE.Vector2(aim.x*2-1,1-aim.y*2),camera);const z=-state.distance+.08,t=(z-raycaster.ray.origin.z)/raycaster.ray.direction.z;return raycaster.ray.origin.clone().addScaledVector(raycaster.ray.direction,t);}
function fireShot(drawPower){if(roundDone){state.shot=1;state.round++;roundDone=false;shots.forEach(s=>scene.remove(s.mesh));shots=[];$('#shootBtn').innerHTML='SHOOT<small>HOLD TO DRAW</small><i class="power-track" id="powerTrack"></i>';$('#shootBtn').classList.remove('charging');refreshHud();return;}
 if(state.shot>5)return;const point=getAimPoint(),origin=new THREE.Vector3(.34,1.48,7.35),distance=origin.distanceTo(point);const speed=(31+(state.upgrades.limbs||0)*4+(state.upgrades.carbon||0)*1.6)*(.78+drawPower*.22);const flight=distance/speed,drop=.5*8.6*flight*flight;const compensated=point.clone();compensated.y+=drop;const direction=compensated.sub(origin).normalize();const arrow=makeArrow();arrow.position.copy(origin);arrow.quaternion.setFromUnitVectors(new THREE.Vector3(0,1,0),direction);shots.push({mesh:arrow,velocity:direction.multiplyScalar(speed),origin,finished:false});state.shot++;if(state.shot>5)roundDone=true;refreshHud();sound(440+drawPower*160);}
function finishShot(shot,point){shot.finished=true;const offset=Math.hypot(point.x-targetCenter.x,point.y-targetCenter.y),hit=offset<=targetRadius,bull=offset<=targetRadius*.17;let reward=0;
 if(hit){const target=targets[state.targetId];reward=bull?target.bull:target.hit;state.coins+=reward;toast(bull?"BULL'S-EYE!":'TARGET HIT',`+${reward} coins · ${Math.max(0,Math.round((1-offset/targetRadius)*100))}% accuracy`,bull?'gold':'lime');sound(bull?880:650);save();refreshHud();
  const marker=makeArrow();marker.position.set(point.x,point.y,-state.distance+.19);marker.quaternion.copy(shot.mesh.quaternion);arrowStamps.push(marker);if(arrowStamps.length>12){const old=arrowStamps.shift();scene.remove(old);}
 }else{toast('JUST WIDE','Adjust for the crosswind and try again.','');}
 if(roundDone){setTimeout(()=>{if(roundDone){$('#shootBtn').innerHTML='NEW ROUND<small>5 ARROWS · TAP TO RESTART</small>';toast('END OF ROUND',`Your purse: ${state.coins} coins`,'gold');}},800);}
}
